// Clean-room GTA: San Andreas SCM opcode arity & symbol table derived from gta-reversed and SBL metadata.
// Positive `Fixed(arity)` = exact number of typed `eScriptParameterType` arguments;
// `VarArgTerminated` = vararg argument list terminated by `0x00` (`0x004F`, `0x0913`);
// `SwitchTable` = 18-arg switch jump table (`0x0871`, `0x0872`).

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OpcodeShape {
    Fixed(u8),
    VarArgTerminated,
    SwitchTable,
}

#[derive(Debug, Clone, Copy)]
pub struct OpcodeMeta {
    pub id: u16,
    pub name: &'static str,
    pub shape: OpcodeShape,
    pub is_condition: bool,
}

