pub fn lookup_opcode_meta(opcode: u16) -> Option<OpcodeMeta> {
    SA_OPCODE_TABLE
        .binary_search_by_key(&opcode, |m| m.id)
        .ok()
        .map(|idx| SA_OPCODE_TABLE[idx])
}
